input.command:
head -n -2 tests/rotate_test.sh > /tmp/t && cat >> /tmp/t <<'EOF'
for i in 3 4 5 6; do echo $i > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
[ "$(ls "$d/logs" | grep -c '^app.log.[0-9]')" = 3 ] || { echo "local keep"; fail=1; }
[ "$(ls "$d/archive" | wc -l)" = 3 ] || { echo "archive keep"; fail=1; }
[ -e "$d/archive/app.log.20261001" ] && { echo "oldest archive kept"; fail=1; }
[ -e "$d/archive/app.log.20261006" ] || { echo "newest archive missing"; fail=1; }
rm -rf "$d"
exit $fail
EOF
cp /tmp/t tests/rotate_test.sh; tail -9 tests/rotate_test.sh; bash scripts/verify.sh && echo PASS
